// GENERATED by pawlegends/tools/vendor-sim.mjs from pawlegends/src/chat/personas.ts. Do not edit:
// change the bot chatter there and run `npm run vendor-sim` in pawlegends/ (CI runs `vendor-sim:check`).
/**
 * Bot chat personalities (docs/plans/moba/MATCH-CHAT.md §5.4): drawn per bot per match from the chatter's PRNG, and
 * the surface layer that dresses a bank line the way that persona types it (casing, abbreviations, punctuation,
 * elongation, an emoji). Typos are typos.ts. Never adds a word that is not in the base line, except the fixed
 * abbreviation and expansion tables below (all ordinary match talk).
 *
 * Pure, no imports outside src/chat: vendored verbatim into backend/src/vendor/pawlegends-chat.
 */
import type { Rng } from './rng';

export type PersonaKind = 'silent' | 'terse' | 'chatty' | 'emoji' | 'proper';

export interface Persona {
  kind: PersonaKind;
  device: 'phone' | 'desktop';
  /** Typing speed, characters per second. */
  cps: number;
  /** Chance of one typo per line. */
  typo: number;
  /** Share of typos followed by a "*word" fix (chatty only). */
  fixRate: number;
  /** Chance of a stretched last word ("niceee"). */
  elong: number;
  /** The persona's own end punctuation habit. */
  punct: '' | '!' | '…';
  /** Weight of cats-vs-dogs flavour lines. */
  flavour: number;
  /** Chance a line is all lowercase. */
  lower: number;
}

export const PERSONA_WEIGHTS: Readonly<Record<PersonaKind, number>> = Object.freeze({ silent: 0.45, terse: 0.25, chatty: 0.1, emoji: 0.08, proper: 0.12 });
const KINDS: readonly PersonaKind[] = ['silent', 'terse', 'chatty', 'emoji', 'proper'];
const BASE_TYPO: Readonly<Record<PersonaKind, number>> = Object.freeze({ silent: 0, terse: 0.03, chatty: 0.06, emoji: 0.02, proper: 0.01 });

export function drawPersona(rng: Rng): Persona {
  const kind = KINDS[rng.weighted(KINDS.map((k) => PERSONA_WEIGHTS[k]))];
  const phone = rng.chance(0.7);
  const cps = phone ? rng.range(3.0, 4.5) : rng.range(5, 7);
  const punctRoll = rng.next();
  return {
    kind,
    device: phone ? 'phone' : 'desktop',
    cps,
    // phones make a few more typos
    typo: Math.min(0.08, BASE_TYPO[kind] * (phone ? 1.3 : 1)),
    fixRate: kind === 'chatty' ? 0.25 : 0,
    elong: kind === 'proper' ? 0 : rng.range(0, 0.1),
    punct: kind === 'terse' || kind === 'proper' ? '' : punctRoll < 0.6 ? '' : punctRoll < 0.85 ? '!' : '…',
    // a silent player's rare "gg" is typed bare
    lower: kind === 'terse' || kind === 'silent' ? 1 : kind === 'chatty' ? 0.7 : kind === 'emoji' ? 0.8 : 0,
    flavour: rng.range(0, 0.08),
  };
}

